CREATE TABLE enquiries (id text PRIMARY KEY, channel text, date date, time text, week text, weekday text, after_hours text, segment text, location text, outcome text, decline_reason text, reply_hours numeric, answered_within_1h text, check_real_project text, check_service_area text, check_timeline text, check_budget text, check_decision_maker text, asked_price text, price_quoted text, next_step text, summary text);
